"""Build the scientific report section from saved development experiment records."""
import json
from pathlib import Path


def generate(output):
    b=json.loads(Path('results/experiments/baselines-local-v1/summary.json').read_text());h=json.loads(Path('results/hpo/hgb-tpe-v1/summary.json').read_text());d=json.loads(Path('results/hmm/hgb-hmm-v1/summary.json').read_text());eda=json.loads(Path('results/eda/initial-validation-v2/metadata.json').read_text());prep=json.loads(Path('results/eda/preparation-v1/preparation.json').read_text())
    names={'logistic_regression':'Logistic Regression','knn':'Distance-weighted KNN','random_forest':'Random Forest','extra_trees':'Extra Trees','hist_gradient_boosting':'HistGradientBoosting'}
    lines=['## 2. Dataset Understanding','', 'This scientific section uses only the supplied 80 training and ten student-testing trips. Reserved evaluator data were not available and were never inspected. Every number below is generated from saved JSON records by `src/evaluation/scientific_report.py`. Pointwise scores use the explicit **provisional** alignment policy `pathsnap-scoring-v0`; organizer clarification remains necessary.','','### 2.1 Inventory, geometry and cleaning','', '| Partition | Trips | GPS observations | Nodes | Directed arcs |','|---|---:|---:|---:|---:|']
    for p in ['train','student_test']:
        r=eda['summaries'][p];lines.append(f"| {p} | {r['trips']} | {r['observations']:,} | {r['nodes']:,} | {r['arcs']:,} |")
    lines += ['', 'All supplied GPS/node coordinates and numeric values passed validation; timestamps increased strictly. Exactly one-second steps account for 96.50% of training and 98.62% of student-testing steps, but maximum gaps are 153,064s and 210s respectively. Gap handling is therefore necessary. There are 100 training and six student-test zero-length arcs: these retain their original graph IDs and topology but cannot be geometric candidates. Supplied reference traversals contain 67/255 repeated occurrences and 13/1 nonadjacent successive arc pairs (train/student test). References must retain occurrence order and disconnected geometry.', '', 'Parsing preserves original row-based observation, node and arc IDs. Malformed physical rows fail explicitly instead of being silently skipped. Invalid observations in future inputs remain in place with validity/reason masks; inference does not silently delete them. Numeric feature imputation uses medians fitted only on fold training rows. No learned transformation sees validation or student-test rows during fitting.', '', 'Road geometry is a straight directed node-to-node segment, projected separately per trip using WGS84 local azimuthal-equidistant coordinates centered on the median valid GPS location. `always_xy` fixes longitude/latitude order. Physical calculations use metres; browser geometry stays WGS84 `[lon, lat]`. This avoids applying Euclidean distances to degrees. Directed connectivity follows supplied arcs; unavailable traffic rules and turn restrictions are not invented.', '', '![Trip sizes and timestamp gaps](results/figures/data-quality-v1/trip-sizes-and-gaps.png)', '', '*Figure 1. All 90 permitted trips, separated by partition. Maximum time gaps use a log scale. Source: `results/eda/initial-validation-v2/trips.csv`.*', '', '### 2.2 Reference alignment and candidate accounting','', 'A `.route` file is a road traversal, not one label per GPS row. Offline supervision uses monotone dynamic programming over traversal occurrences, including nonconsecutive repeats. Free endpoints and forward skips allow unobserved intervening arcs. Costs combine capped squared metric projection residual (20m scale, 100m cap) and a directional penalty of two when motion is reliable. A valid observation is scorable only if its aligned residual is at most100m. Low geometric margins below3m are diagnosed, not removed. This derived policy is not certified organizer ground truth.', '', '| Partition | Original rows | Scorable | Unscorable | Candidate covered | Candidate misses |', '|---|---:|---:|---:|---:|---:|']
    for p in ['train','student_test']:
        rows=[r for r in prep['records'] if r['partition']==p];tot=lambda k:sum(r[k] for r in rows)
        lines.append(f"| {p} | {tot('observations'):,} | {tot('scorable'):,} | {tot('unscorable'):,} | {tot('covered'):,} | {tot('candidate_misses'):,} |")
    lines += ['', 'The substantial training unscorable count is a limitation, not discarded evidence. Accuracy includes all scorable candidate misses and unmatched rows as errors; a separate original-row score and raw/scorable counts expose the denominator. Alternative official alignment could change both scores and model rankings.', '', '![Target coverage](results/figures/data-quality-v1/target-coverage.png)', '', '*Figure 2. Complete row accounting under provisional alignment; candidate misses are retained in accuracy denominators. Source: `results/eda/preparation-v1/preparation.json`.*', '', 'Indexed candidate generation uses length-binned segment-midpoint cKDTrees, conservatively querying radius plus maximum half-segment length and then refining exact segment projections. Radius100m/top8 and deterministic distance/arc-ID tie ordering are fixed across models. Features are constructed before reference access: metric and log distance, heading cosine/validity, log arc length, projection fraction, speed, time delta and distance excess over the nearest candidate. Trip-local IDs and references are excluded from features.', '', '### 2.3 Leakage controls and metrics','', 'Five seeded (81) GroupKFold splits hold out whole training trips: 64fit/16validation per fold and every one of the80 training trips held out once. Fit observations are deterministically capped at400 scorable rows per training trip; all their candidate rows are retained. Validation and student testing are unsampled. A median imputer is fitted inside every model pipeline; LR/KNN also use fold-fitted StandardScaler. Predictions load only track/nodes/arcs. A separate post-prediction scorer alone reads references, and returns only aggregates.', '', 'Accuracy is pooled over scorable observations; Macro F1, precision and recall average per-trip road-class macro values over truth union matched predictions. Unmatched predictions cause false negatives. Conditional log loss uses only observations whose aligned arc occurs in candidates and describes normalized relevance, not calibrated confidence. Candidate miss rate is reported separately. Sequence similarity is one minus normalized Levenshtein distance of compressed observed-arc runs, not full-route accuracy. Continuity is the proportion of consecutive valid pairs within30s with a feasible directed route under the fixed physical bound; unmatched pairs fail. There is no global road-class confusion matrix because arc IDs are trip-local.', '', '## 3. Model Experimentation','', f"Five distinct algorithms completed identical grouped comparisons, with source `{b['source_git_sha']}` and local total elapsed time {b['elapsed_s']:.2f}s at two threads. Complete per-fold/per-trip records, warnings, configurations and fitted assets are retained under `results/experiments/baselines-local-v1`. No model is credited for the HMM decoder as an additional classifier.", '', '| Model | Training CV trip Macro F1 | Student accuracy | Student trip Macro F1 | Total seconds |', '|---|---:|---:|---:|---:|']
    for r in b['results']:lines.append(f"| {names[r['model_name']]} | {r['cv']['macro_f1']:.6f} | {r['student_test']['top1_accuracy']:.6f} | {r['student_test']['macro_f1']:.6f} | {r['elapsed_s']:.2f} |")
    lines += ['', '| Model | Student precision | Student recall | Conditional log loss |','|---|---:|---:|---:|']
    for r in b['results']:lines.append(f"| {names[r['model_name']]} | {r['student_test']['precision_macro']:.6f} | {r['student_test']['recall_macro']:.6f} | {r['student_test']['log_loss']:.6f} |")
    lines += ['', '| Model | Family / key initial settings | Student continuity | Student scoring ms | Final refit ms |', '|---|---|---:|---:|---:|']
    for r in b['results']:
        configuration=json.dumps(r['configuration'],sort_keys=True)
        lines.append(f"| {names[r['model_name']]} | {r['family']}; {configuration} | {r['student_test']['route_continuity']:.6f} | {r['student_test']['candidate_scoring_ms']:.2f} | {r['refit']['fit_ms']:.2f} |")
    lines += ['', 'Student scoring timings include saved preprocessing, estimator scoring and per-observation selection; exclude cached candidate/feature construction, graph routing and reference metrics. Full-facade timings appear in section5. Final refit fits the sampled observations across all80 training trips. The source JSON retains per-fold fit time and warnings.']
    lines += ['', '![Five-model grouped comparison](results/figures/baselines-v1/training-cv-macro-f1.png)', '', '*Figure 3. Training-CV means; error bars are standard deviations of five fold means, not confidence intervals or independent point-level uncertainty.*', '', '![Student testing metrics](results/figures/baselines-v1/student-test-accuracy-f1.png)', '', '*Figure 4. Pooled accuracy and mean trip Macro F1 answer different weighting questions. Student data describe generalization and are excluded from model selection.*', '', '![Conditional loss](results/figures/baselines-v1/student-test-conditional-log-loss.png)', '', '*Figure 5. Conditional candidate-distribution log loss, lower is better. Candidate misses remain separate.*']
    descriptions={
      'logistic_regression':('A compact linear baseline tests whether geometric evidence combines approximately linearly. L2 regularization limits coefficient growth; standardized features support stable optimization. It cannot express all interactions among heading, distance and local geometry.','Regularized binary log loss; C1,lbfgs,max_iter500.'),
      'knn':('Distance-weighted neighbors can learn nonlinear local feature patterns with little fitted parameterization. Standardization is essential for its metric. Prediction retains the training rows and was costly on this workload; sparse neighborhoods can also give overconfident relevance.','15 distance-weighted neighbors; kd_tree,leaf_size40. No iterative fitted loss optimizer.'),
      'random_forest':('Bagged randomized trees model nonlinear interactions and resist simple feature scaling problems. Depth and leaf-size limits constrain fit complexity. Its CV result was close to HGB, and student accuracy exceeded untuned HGB, but its measured training/evaluation cost was larger.','64 bootstrap trees; Gini splits,max_depth16,min_samples_leaf8,seed81.'),
      'extra_trees':('Genuinely randomized split thresholds offer a distinct ensemble and inexpensive fitting here. Extra randomization can reduce variance but may lose fine distance/heading boundaries. It was competitive but below RF/HGB on the predefined CV objective.','64 randomized-threshold trees; Gini splits,max_depth16,min_samples_leaf8,seed81.'),
      'hist_gradient_boosting':('Sequential histogram trees model geometric-feature interactions with compact assets. Learning rate, leaf count, iterations and regularization require control. It led the predefined CV Macro F1 at low measured cost and was selected for TPE; the small lead over RF should not be treated as a statistically established universal advantage.','Binary log loss;100iterations,15leaves,min_samples_leaf30,learning_rate0.1,L2=1,early_stoppingFalse,seed81.')}
    for r in b['results']:
        name=r['model_name'];reason,config=descriptions[name]
        lines += ['',f"### 3.{list(names).index(name)+1} {names[name]}",'',reason,'',config,'',f"Fit-sample accuracy {r['fit_sample']['top1_accuracy']:.6f}; held-out CV accuracy {r['cv']['top1_accuracy']:.6f}; student accuracy {r['student_test']['top1_accuracy']:.6f}. Fit rows are sampled whereas evaluation is unsampled: the gap is descriptive evidence, not a controlled overfit estimate. A high training score alone does not establish generalization. Detailed fold warnings and metrics are retained in `{name}.json`."]
        lines += ['', f"![{names[name]} local-road confusion](results/experiments/confusion-v1/{name}.png)", '', '*Diagnostic matrix for student trip00000052; both axes use the complete ordered set of trip-local road classes. Original arc IDs are listed in the adjacent class-order JSON. This is not a global cross-trip class matrix.*']
    lines += ['', 'Per-model confusion matrices preserve original trip-local arc IDs and unmatched=-1 in the separate `results/experiments/confusion-v1` supplement. Each PNG shows the complete matrix for student trip00000052; class-order JSON maps matrix indices back to original IDs. Counts are not pooled across different road networks. This visualization is diagnostic and does not determine the selected model.', '', '## 4. Bayesian Hyperparameter Optimisation','', 'Optuna4.3.0 TPESampler(seed81) executed12 real sequential trials: four random startup trials followed by eight adaptive TPE trials. The objective is mean held-out-trip Macro F1 over the exact same five training-group folds, sampling and features. No student-test or evaluator metric enters the objective. Search space: iterations60–180; leaves7–31; minimum samples per leaf15–80; learning rate0.03–0.2 logarithmic; L2 regularization0.01–10 logarithmic. There was no random-search substitution for Bayesian tuning and no pruning of difficult folds.', '', f"Best trial {h['best_trial']} had training-CV Macro F1 {h['cv']['macro_f1']:.6f}, compared with {next(r for r in b['results'] if r['model_name']=='hist_gradient_boosting')['cv']['macro_f1']:.6f} untuned. Best parameters: `{json.dumps(h['best_params'],sort_keys=True)}`. Its final classifier-only student accuracy is {h['student_test']['top1_accuracy']:.6f} and trip Macro F1 {h['student_test']['macro_f1']:.6f}. Selection uses CV, not that descriptive student-test change.", '', f"Completed trial compute sums {h['completed_trial_compute_s']:.2f}s at four threads. The original process ended unexpectedly with143 after11 completed trials while the final sampled trial was running. SQLite retained its parameters; explicit recovery reran exactly those parameters, without replacing completed trials or sampling extras. `recovery.json` records both source revisions. Recovery-invocation elapsed {h['elapsed_s']:.2f}s includes its final trial and refit; it is not total tuning time. Interrupted partial-trial compute is unavailable. Full SQLite storage,12trial files,fold metrics and failures/recovery provenance are retained under `results/hpo/hgb-tpe-v1`.", '', '![Actual TPE history](results/figures/final-v1/bayesian-trials.png)', '', '*Figure 6. Actual complete trial values and running best; adaptive TPE begins after the first four startup trials.*', '', '![Tuned versus untuned](results/figures/final-v1/tuned-untuned.png)', '', '*Figure 7. Same training folds and objective; the improvement is modest. CV used for tuning is selection evidence, not an unbiased nested-CV estimate.*', '', '## 5. HMM and Viterbi','', 'The hidden state is a directed candidate arc together with its projected position. Emission scores are clipped, per-observation normalized binary relevance from the selected fitted classifier. They are discriminative scores, not calibrated GPS likelihoods. Transition log scores penalize the absolute difference between feasible directed route distance and observed metric displacement, divided by25m. Directed travel includes source-arc remainder, a Dijkstra connector and target-arc prefix. No reverse edges are invented; small backward projection noise up to15m on the same arc is treated as stationary.', '', 'A65m/s bound plus50m slack limits travel for each observed time interval. Empty candidates, time gaps above30s, nonpositive time intervals and all-unreachable transitions terminate or restart the lattice. Log-space Viterbi uses backpointers and subtracts a common offset per step for stability. The recurrence maximizes previous log score plus transition score plus emission log score. Route geometry consists of actual observed and connecting arcs, with disconnected pieces kept separate. The hybrid scoring assumptions follow the map-matching framework of Newson and Krumm (2009), adapted to learned emissions; they do not claim calibrated generative probabilities or unavailable real-world traffic restrictions.', '', 'All decoder parameters were fixed before the student comparison. Each of the ten student-testing trips ran twice through the actual reference-free facade, followed by the isolated scorer. All prediction invariants and development visualization schemas passed. Classifier-only aggregate metrics matched the independent cached HPO evaluation to1e-12 for all six checked metrics.', '', '| Metric | Tuned classifier only | Tuned classifier + HMM |', '|---|---:|---:|']
    for key in ['top1_accuracy','macro_f1','precision_macro','recall_macro','candidate_miss_rate','route_continuity','sequence_arc_similarity','log_loss']:
        lines.append(f"| {key.replace('_',' ')} | {d['aggregates']['classifier_only']['metrics'][key]:.6f} | {d['aggregates']['hmm_viterbi']['metrics'][key]:.6f} |")
    lines += ['', '![Classifier and HMM comparison](results/figures/final-v1/classifier-hmm.png)', '', '*Figure 8. Measured development scores under provisional alignment. Sequence similarity compares observed-arc runs, not a complete reference traversal.*', '', 'Conditional log loss is identical because it evaluates the same classifier emissions; a Viterbi path is not an HMM posterior. The HMM improved both pointwise and continuity metrics here, but direction ambiguity, missing candidates, network/reference mismatch and unmodeled traffic rules remain limitations.', '', f"Connected route pieces fell from {d['aggregates']['classifier_only']['route_pieces']} to {d['aggregates']['hmm_viterbi']['route_pieces']}. Full facade inference across ten trips took {d['aggregates']['classifier_only']['inference_total_ms']/1000:.2f}s classifier-only and {d['aggregates']['hmm_viterbi']['inference_total_ms']/1000:.2f}s HMM on this host, excluding separate scoring. These are local measurements, not a LAN guarantee. The portable checksummed bundle is `artifacts/hgb-hmm-v1`. Both modes retain19,160 original observations;19,143 are provisionally scorable,17 unscorable and84 scorable candidate misses.", '', 'Development-only GPS/network/reference/prediction exports are under `results/hmm/hgb-hmm-v1/visualisation`. They supply B’s separate Folium generator and never enter UI/API inference inputs. Reference geometry is restricted to these permitted development exports. API evaluation exposes aggregate metrics only.', '', '### Scientific evidence and remaining limits','', f"EDA source `{eda['source_git_sha']}`; baseline source `{b['source_git_sha']}`; initial HPO source `{h['source_git_sha']}` plus explicit recovery; trained comparison source `{d['source_git_sha']}`. Full hashes, configuration, data fingerprint, dependencies, per-fold/trip records and feature policy are in those run directories and the artifact manifest. `results/experiments/source-revision-map.json` resolves earlier metadata-cleanup revisions without altering original run evidence.", '', 'Required external checks remain organizer confirmation of pointwise alignment, reserved evaluator provisioning and the two-physical-laptop demonstration. Student-test gains do not establish final evaluator performance. Team members should review the interpretation and use `docs/ml/viva-notes.md` to explain the implementation.', '', 'Primary method reference: Paul Newson and John Krumm, *Hidden Markov Map Matching Through Noise and Sparseness*, ACM SIGSPATIAL GIS2009, https://www.microsoft.com/en-us/research/publication/hidden-markov-map-matching-noise-sparseness/. The user supplied an Uber Maps talk summary as background; no video was inspected. ECC was reviewed for development workflow guidance only, as documented in `docs/ml/ecc-review.md`; no third-party task implementation or model weights were copied.']
    a=next(r for r in d['trips'] if r['trip_id']=='00000007' and r['decoder']=='classifier_only');c=next(r for r in d['trips'] if r['trip_id']=='00000007' and r['decoder']=='hmm_viterbi')
    lines += ['', '### Counterexample: continuity does not guarantee a correct route', '', f"Student trip00000007 is the observed exception: classifier accuracy {a['metrics']['top1_accuracy']:.6f} fell to {c['metrics']['top1_accuracy']:.6f} after HMM; trip Macro F1 changed from {a['metrics']['macro_f1']:.6f} to {c['metrics']['macro_f1']:.6f}. Thus the pooled improvement is not an improvement on every trip. A connectivity prior can favor a coherent but incorrectly aligned route; identifying the specific cause here requires local reference/map review. We report the regression and did not adjust decoder parameters to this student-test case. See the two per-trip records and actual Folium layers."]
    untuned=next(r for r in b['results'] if r['model_name']=='hist_gradient_boosting')
    comparison=['### Tuned and untuned results under the same definitions', '', '| HGB variant | CV Macro F1 | Student accuracy | Student Macro F1 | Log loss |', '|---|---:|---:|---:|---:|']
    for variant,row in [('Untuned',untuned),('Tuned',h)]:
        comparison.append(f"| {variant} | {row['cv']['macro_f1']:.6f} | {row['student_test']['top1_accuracy']:.6f} | {row['student_test']['macro_f1']:.6f} | {row['student_test']['log_loss']:.6f} |")
    profile=json.loads(Path('results/experiments/selected-profile-v1/summary.json').read_text())
    comparison += ['', 'Common-host inference profile: '+ '; '.join(f"{r['variant']} median {r['median_ms']:.2f}ms" for r in profile['results'])+' across all ten student trips, same four-thread limit, one warmup and three measured passes each. Boundary: saved preprocessing, model scores and per-observation normalization/selection; candidate preparation, graph decoding and reference metrics excluded. See `results/experiments/selected-profile-v1/summary.json`.', '']
    position=lines.index('## 5. HMM and Viterbi');lines[position:position]=comparison
    import csv
    inventory=list(csv.DictReader(Path('results/eda/initial-validation-v2/trips.csv').open()))
    connectivity=['### Network connectivity and geographic extent', '', '| Partition | Weak components per trip (min–max) | Strong components per trip (min–max) | Longitude extent | Latitude extent |', '|---|---:|---:|---|---|']
    for partition in ['train','student_test']:
        rows=[r for r in inventory if r['partition']==partition]
        bounds=lambda key:(min(float(r[key]) for r in rows),max(float(r[key]) for r in rows))
        weak=bounds('weak_components');strong=bounds('strong_components')
        connectivity.append(f"| {partition} | {weak[0]:.0f}–{weak[1]:.0f} | {strong[0]:.0f}–{strong[1]:.0f} | {min(float(r['min_lon']) for r in rows):.3f} to {max(float(r['max_lon']) for r in rows):.3f} | {min(float(r['min_lat']) for r in rows):.3f} to {max(float(r['max_lat']) for r in rows):.3f} |")
    connectivity += ['', 'There were no isolated supplied nodes. Disconnected components make a single connected route unsafe as a default. Extents span different regions, supporting per-trip metric projections. Per-trip file sizes, IDs, components and timestamp statistics remain in the EDA CSV.', '']
    position=lines.index('### 2.2 Reference alignment and candidate accounting');lines[position:position]=connectivity
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text('\n'.join(lines)+'\n')

if __name__=='__main__':generate(Path('report/sections/science.md'))
